lpc['constrained_mean_range'] = 0.062305
lpc['constrained_tied_pct'] = 59.7
for key in ['var_ratio_std', 'var_ratio_range', 'tied_reduction_pp']:
    vals = [s[key] for s in seeds]
    m, s = ms(vals)
    lpc[key] = {'mean': round(m,3), 'std': round(s,3)}

prates = [s['parse_rate'] for s in seeds]
mpr, spr = ms(prates)

summary = {
