    'dataset': 'SciERC',
    'model': 'Qwen3-8B (LoRA merged, scierc-v2)',
    'n_instances': 551,
    'n_samples_per_instance': 8,
    'temperature': 1.0,
    'seeds': [123, 456, 789],
    'n_gold_filtered': {'ner': 529, 're': 397},
    'freeform_qe': qe,
    'freeform_selection_gap': sel,
    'lp_compression': lpc,
    'parse_rate': {'mean': round(mpr,2), 'std': round(spr,2)},
    'constrained_ref': {
        'selection_ner': {'greedy': 0.6182, 'selected': 0.6241, 'gap': 0.0059},
        'selection_re': {'greedy': 0.2913, 'selected': 0.2845, 'gap': -0.0068},
