    },
    'conclusion': {
        'lp_compression_intrinsic': True,
        'evidence': 'Freeform tied_pct=58.37+/-0.65% vs constrained 59.7%. Variance ratio 0.92+/-0.04x. LP compression persists without grammar constraints, confirming it is model/task intrinsic, not a constrained decoding artifact.',
        'qe_ranking_ner': 'VC (0.415+/-0.007) > SJ (0.386+/-0.008) > EM (0.322+/-0.004) > FK (0.307+/-0.019) > LP (0.230+/-0.015)',
        'qe_ranking_re': 'VC (0.308+/-0.008) > LP (0.304+/-0.007) > FK (0.265+/-0.047) > SJ (0.229+/-0.039) > EM (0.115+/-0.019)',
